#include <iostream>
#include <algorithm>
#include <cstdio>
#include <cstring>
using namespace std;

int total_n, total_k, total_p;

int power_mod(int base, int exp) {
    int res = 1;
    int b = base;
    while (exp > 0) {
        if (exp & 1) res = (long long)res * b % total_p;
        b = (long long)b * b % total_p;
        exp >>= 1;
    }
    return res;
}

int get_lowbit_value(int x) {
    return x & (-x);
}

int memo[26][250010];
int fact[250010], inv_fact[250010];

void setup() {
    fact[0] = 1;
    for (int i = 1; i <= total_n; ++i)
        fact[i] = (long long)fact[i - 1] * i % total_p;
    inv_fact[total_n] = power_mod(fact[total_n], total_p - 2);
    for (int i = total_n; i >= 1; --i)
        inv_fact[i - 1] = (long long)inv_fact[i] * i % total_p;
}

int recursive_solve(int current, int S) {
    if (memo[current][S] != -1) return memo[current][S];
    if (S == 0) {
        memo[current][S] = fact[total_n];
        for (int i = 1; i <= current; ++i)
            memo[current][S] = (long long)memo[current][S] * (total_k - i + 1) % total_p;
        return memo[current][S];
    }
    memo[current][S] = 0;
    int U = S - get_lowbit_value(S);
    for (int T = U; T; T = (T - 1) & U)
        memo[current][S] = (memo[current][S] + (long long)inv_fact[S - T] * recursive_solve(current + 1, T)) % total_p;
    memo[current][S] = (memo[current][S] + (long long)inv_fact[S] * recursive_solve(current + 1, 0)) % total_p;
    return memo[current][S];
}

int main() {
    scanf("%d %d %d", &total_n, &total_k, &total_p);
    int result = 1;
    for (int i = 1; i <= total_n; ++i)
        result = (long long)result * total_k % total_p;
    if (total_n % 2 == 0) {
        setup();
        memset(memo, -1, sizeof(memo));
        result = (result - recursive_solve(0, total_n) + total_p) % total_p;
    }
    printf("%d\n", result);
    return 0;
}
